var walls = (object[])args["walls"];
string baseLvl = Tama.Args.Get(args,"baseLevel","Level 2");
string topLvl = Tama.Args.Get(args,"topLevel","Level 3");
var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().ToList();
var lb = levels.First(l=>l.Name==baseLvl); var lt = levels.First(l=>l.Name==topLvl);
var allWT = new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>().ToList();
var seed = allWT.First(w=>w.Name=="Generic - 200mm");
Func<string,double,string,WallType> getType = (name, mm, matName) => {
  var ex = allWT.FirstOrDefault(w=>w.Name==name); if (ex!=null) return ex;
  var wt = (WallType)seed.Duplicate(name);
  var mat = new FilteredElementCollector(doc).OfClass(typeof(Material)).Cast<Material>().FirstOrDefault(m=>m.Name==matName);
  var layer = new CompoundStructureLayer(mm/304.8, MaterialFunctionAssignment.Structure, mat!=null?mat.Id:ElementId.InvalidElementId);
  var cs = CompoundStructure.CreateSimpleCompoundStructure(new List<CompoundStructureLayer>{layer});
  cs.EndCap = EndCapCondition.NoEndCap;
  wt.SetCompoundStructure(cs); allWT.Add(wt); return wt;
};
var tc = getType(Tama.Args.Get(args,"concreteType","BC_Concrete 200mm"),200,"Concrete, Cast In Situ");
var tp = getType(Tama.Args.Get(args,"partitionType","BC_Partition 100mm"),100,"Gypsum Wall Board");
var made = new List<int>();
foreach (var o in walls) {
  var a = (object[])o;
  double x1=Convert.ToDouble(a[0])/304.8, y1=Convert.ToDouble(a[1])/304.8, x2=Convert.ToDouble(a[2])/304.8, y2=Convert.ToDouble(a[3])/304.8;
  double th = Convert.ToDouble(a[4]); string k = a[5].ToString();
  WallType t = k=="c"?tc:tp;
  if (Math.Abs(t.Width*304.8-th)>1) t = getType("BC_Wall "+th+"mm",th,"Concrete, Cast In Situ");
  var line = Line.CreateBound(new XYZ(x1,y1,lb.Elevation), new XYZ(x2,y2,lb.Elevation));
  var w = Wall.Create(doc, line, t.Id, lb.Id, (lt.Elevation-lb.Elevation), 0, false, k=="c");
  w.get_Parameter(BuiltInParameter.WALL_HEIGHT_TYPE).Set(lt.Id);
  w.get_Parameter(BuiltInParameter.WALL_KEY_REF_PARAM).Set(0);
  w.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("Block C");
  made.Add(w.Id.IntegerValue);
}
return new{created=made.Count, concreteType=tc.Name, partitionType=tp.Name, firstId=made.FirstOrDefault(), lastId=made.LastOrDefault()};
